//===============================================================
// Namespace
//===============================================================

namespace AppCore.Application.Settings.ServiceSettings;


//===============================================================
// Configure Scheduled Service DTO
//
// Records are generated by Service Policy, so there is no Create :
// saving the price (first time or again) configures the row.
//===============================================================

public class ConfigureScheduledServicesDto
{
    //===========================================================
    // Primary Key
    //===========================================================

    public long ScheduledServiceId
    {
        get;
        set;
    }


    //===========================================================
    // Charges
    //===========================================================

    // Paid services : required (> 0); Free services : 0
    public decimal CustomerCharge
    {
        get;
        set;
    }


    // Free services : required (> 0); Paid services : 0
    public decimal BrandReimbursement
    {
        get;
        set;
    }


    //===========================================================
    // Status & Control
    //===========================================================

    public string Remarks
    {
        get;
        set;
    } = string.Empty;


    public bool IsActive
    {
        get;
        set;
    } = true;
}